import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d as S,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"分段路由","description":"","frontmatter":{"title":"分段路由","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/segment-routing.md","filePath":"cs/segment-routing.md","lastUpdated":1789023840000}'),E={name:"cs/segment-routing.md"};function P(h,a,c,I,m,_){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="分段路由" tabindex="-1">分段路由 <a class="header-anchor" href="#分段路由" aria-label="Permalink to &quot;分段路由&quot;">​</a></h1><div class="epigraph"><p>路径编码进标签栈或 IPv6 段列表，中间节点只执行「到某前缀 / 某邻接」的段；状态从核心移到头节点。</p><footer>—— 据 RFC 8402 Segment Routing 架构；RFC 8660 SR-MPLS；RFC 8754 SRv6 整理</footer></div><p><a href="/cs/mpls">上一课</a> 用 RSVP 在中间保 LSP 状态。缺口是<strong>无状态 TE</strong>：SR 把段（前缀 SID、邻接 SID）叠在包头，IGP 洪泛 SID，头节点算栈。本课不把 ECMP 哈希极化写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RSVP-TE 每条 LSP 在沿途维持软状态，规模随需求矩阵涨。SR-MPLS：栈里的标签是段，弹出即执行下一段。SRv6：IPv6 目的地址依次为段，中间匹配 SID。TI-LFA 用段绕开失败邻接，预计算比 RSVP 简单。头节点仍要算约束路径，复杂度没消失，只是移走。</p><p>不要把 SR 写成源路由的任意互联网：域内受 SID 空间与过滤约束，域间仍 BGP。</p><p><span class="marginnote">RFC 8402。IS-IS/OSPF 用 TLV 带 SID，接住 IS-IS 课的可扩展性。本课不把 SR-TE 策略的全部 BSID 写完。</span></p><h3 id="状态移到头端" tabindex="-1">状态移到头端 <a class="header-anchor" href="#状态移到头端" aria-label="Permalink to &quot;状态移到头端&quot;">​</a></h3><p>中间执行段指令，无每 LSP 软状态。邻接 SID 钉链路，前缀 SID 仍可 ECMP。外部注入 SID 要过滤。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：RSVP 中间状态 vs SR 头端状态。画：IGP 洪泛 SID → 头端压栈 → 沿途执行。与 5G 切片对照：都是「把路径当资源」；一个在 WAN，一个在 RAN。</p>',11)),(e(),n(d,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IGP%5B%22IGP%20%E9%80%9A%E5%91%8A%20SID%22%5D%20--%3E%20HEAD%5B%22%E5%A4%B4%E7%AB%AF%E5%8E%8B%E6%AE%B5%E6%A0%88%22%5D%0A%20%20HEAD%20--%3E%20SEG%5B%22%E4%B8%AD%E9%97%B4%E6%89%A7%E8%A1%8C%E4%B8%80%E6%AE%B5%22%5D%0A%20%20SEG%20--%3E%20NEXT%5B%22%E5%BC%B9%E5%87%BA%E4%B8%8B%E4%B8%80%E6%AE%B5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[S(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ECMP：前缀 SID 仍可在等代价边上哈希，邻接 SID 钉死一条链路——TE 用后者钉热点。MPLS 服务（L3VPN）可继续用内层标签，外层改 SR。RPKI 仍在 BGP 边；SR 不验证用户源地址。</p><p>SRv6 头开销更大，与巨帧/MTU 课衔接：路径 MTU 更易踩。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入网络编程的全部 End.X 行为清单。ECMP 与哈希是下一课。后课默认：SR 是无状态中间的源路由式 TE。</p><p>过滤器必须防外部注入 SID，否则成攻击面。</p><p>上一课留下的缺口在本课收口；「分段路由」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/ecmp-hashing">ECMP 与哈希</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>段是指令；栈在头端，中间无每 LSP 状态。</li><li>IGP 分发 SID；邻接 SID 钉链路。</li><li>SRv6 与 SR-MPLS 是两种数据面。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 8402；RFC 8660；RFC 8754。</li></ul>',10))])}const A=i(E,[["render",P]]);export{u as __pageData,A as default};
